import { expect, test } from "@playwright/test";

import { blur, currentSrc, demoLayout, framesDrawn, isGray, openDemo, sampleCanvas, startPlayback, videoState } from "./helpers";

// All tests here use the deterministic DEMO/TEST media generated by the backend
// with FFmpeg, so they pass without YouTube. See live-youtube.spec.ts for that.

test("preparation walks through explicit states before playback", async ({ page }) => {
  const layout = await demoLayout(page, "sweep");
  await page.goto("/watch?demo=sweep");
  const panel = page.getByTestId("preparation");
  await expect(panel).toBeVisible();
  await expect(panel).toContainText("downloads and prepares the whole video before playback");

  const seen = new Set<string>();
  await expect
    .poll(
      async () => {
        const state = await panel.getAttribute("data-state", { timeout: 200 }).catch(() => null);
        if (state) seen.add(state);
        return (await panel.count()) === 0;
      },
      { timeout: 60_000, intervals: [100] },
    )
    .toBe(true);
  expect([...seen].some((s) => ["downloading", "processing"].includes(s))).toBe(true);

  await startPlayback(page);
  await expect(page.getByTestId("media-details")).toContainText("transcoded to H.264/AAC");
  const sample = await sampleCanvas(page, layout);
  expect(sample.width / sample.height).toBeCloseTo(4 / 3, 1);
});

test("actual video frames reach the canvas and change during playback", async ({ page }) => {
  const layout = await openDemo(page, "bars");

  // The visible picture is the canvas; the decoding element is present but transparent.
  const decoder = page.locator("video.decoder");
  expect(await decoder.evaluate((v) => getComputedStyle(v).opacity)).toBe("0");
  expect(await decoder.evaluate((v) => getComputedStyle(v).display)).not.toBe("none");
  await expect(page.getByTestId("video-canvas")).toBeVisible();

  const first = await sampleCanvas(page, layout);
  await page.waitForTimeout(1200);
  const second = await sampleCanvas(page, layout);

  expect(first.mode).toBe("video-frame-callback");
  expect(second.frames).toBeGreaterThan(first.frames);
  expect(second.hash).not.toBe(first.hash);
  expect(second.bar).toBeGreaterThan(first.bar);
  // The white time bar encodes each frame's timestamp: it must agree with the media clock.
  for (const sample of [first, second]) {
    expect(Math.abs(sample.bar - sample.time / sample.duration)).toBeLessThan(0.06);
  }
  // Pixel-exact colours from the decoded H.264 frame.
  expect(second.red[0]).toBeGreaterThan(200);
  expect(second.red[1]).toBeLessThan(60);
  expect(second.green[1]).toBeGreaterThan(180);
});

test("exactly one frame loop: draws track the 30 fps source, not a multiple of it", async ({ page }) => {
  await openDemo(page, "bars");
  const before = await framesDrawn(page);
  const t0 = (await videoState(page)).time;
  await page.waitForTimeout(2000);
  const drawn = (await framesDrawn(page)) - before;
  const elapsed = (await videoState(page)).time - t0;
  // A duplicated rVFC loop would draw every presented frame twice (~60/s).
  expect(drawn).toBeLessThanOrEqual(Math.ceil(elapsed * 30 * 1.15) + 3);
  expect(drawn).toBeGreaterThan(elapsed * 30 * 0.4);
});

test("pause holds the frame and resume continues", async ({ page }) => {
  const layout = await openDemo(page, "bars");
  await page.getByRole("button", { name: "Pause" }).click();
  await expect.poll(async () => (await videoState(page)).paused).toBe(true);
  await page.waitForTimeout(300);
  const a = await sampleCanvas(page, layout);
  await page.waitForTimeout(800);
  const b = await sampleCanvas(page, layout);
  expect(b.hash).toBe(a.hash);
  expect(b.frames).toBe(a.frames);
  expect(b.time).toBe(a.time);

  await page.getByRole("button", { name: "Play", exact: true }).click();
  await page.waitForTimeout(800);
  const c = await sampleCanvas(page, layout);
  expect(c.paused).toBe(false);
  expect(c.frames).toBeGreaterThan(b.frames);
  expect(c.hash).not.toBe(b.hash);
});

test("seeking (slider and keyboard) redraws the canvas at the new position, even while paused", async ({ page }) => {
  const layout = await openDemo(page, "bars");
  await page.getByRole("button", { name: "Pause" }).click();

  await page.getByRole("slider", { name: "Seek" }).fill("10");
  await expect.poll(async () => Math.abs((await videoState(page)).time - 10)).toBeLessThan(0.3);
  await expect.poll(async () => (await sampleCanvas(page, layout)).bar).toBeGreaterThan(0.46);
  expect((await sampleCanvas(page, layout)).bar).toBeLessThan(0.54);

  // Keyboard (document-level shortcuts): Home -> start, "7" -> 70 %.
  await blur(page);
  await page.keyboard.press("Home");
  await expect.poll(async () => (await sampleCanvas(page, layout)).bar).toBeLessThan(0.03);
  await page.keyboard.press("7");
  await expect.poll(async () => Math.abs((await sampleCanvas(page, layout)).bar - 0.7)).toBeLessThan(0.04);
  // Digits also work while the seek slider has focus (they have no native meaning there).
  await page.getByRole("slider", { name: "Seek" }).focus();
  await page.keyboard.press("2");
  await expect.poll(async () => Math.abs((await sampleCanvas(page, layout)).bar - 0.2)).toBeLessThan(0.04);
  expect((await videoState(page)).paused).toBe(true);
});

test("grayscale effect is applied while rendering (paused and playing)", async ({ page }) => {
  const layout = await openDemo(page, "bars");
  await page.getByRole("button", { name: "Pause" }).click();
  const before = await sampleCanvas(page, layout);
  expect(isGray(before.red)).toBe(false);

  const toggle = page.getByRole("button", { name: /Grayscale/ });
  await toggle.click();
  await expect(toggle).toHaveAttribute("aria-pressed", "true");
  await expect.poll(async () => isGray((await sampleCanvas(page, layout)).red)).toBe(true);
  const gray = await sampleCanvas(page, layout);
  // Rec. 709 luma of pure red ≈ 0.2126 × 255 ≈ 54.
  expect(gray.red[0]).toBeGreaterThan(35);
  expect(gray.red[0]).toBeLessThan(75);

  await page.getByRole("button", { name: "Play", exact: true }).click();
  await page.waitForTimeout(600);
  const playing = await sampleCanvas(page, layout);
  expect(playing.frames).toBeGreaterThan(gray.frames);
  expect(isGray(playing.red)).toBe(true);
  expect(isGray(playing.green)).toBe(true);

  await blur(page);
  await page.keyboard.press("g");
  await expect.poll(async () => (await sampleCanvas(page, layout)).red[0]).toBeGreaterThan(200);
});

test("other effects and the rAF fallback renderer", async ({ page }) => {
  const layout = await openDemo(page, "bars", "&render=raf");
  const a = await sampleCanvas(page, layout);
  expect(a.mode).toBe("animation-frame");
  await page.waitForTimeout(800);
  const b = await sampleCanvas(page, layout);
  expect(b.frames).toBeGreaterThan(a.frames);
  expect(b.hash).not.toBe(a.hash);

  await page.getByLabel("Visual effect").selectOption("invert");
  await expect.poll(async () => (await sampleCanvas(page, layout)).red[1]).toBeGreaterThan(190); // red -> cyan
});

test("player controls: volume, mute, speed and fullscreen", async ({ page }) => {
  await openDemo(page, "bars");
  await page.getByRole("button", { name: "Mute" }).click();
  expect((await videoState(page)).muted).toBe(true);
  await page.getByRole("button", { name: "Unmute" }).click();
  expect((await videoState(page)).muted).toBe(false);

  await page.getByRole("slider", { name: "Volume" }).fill("0.4");
  await expect.poll(async () => (await videoState(page)).volume).toBeCloseTo(0.4, 2);
  await blur(page);
  await page.keyboard.press("ArrowDown");
  await expect.poll(async () => (await videoState(page)).volume).toBeCloseTo(0.35, 2);
  await page.keyboard.press("m");
  expect((await videoState(page)).muted).toBe(true);

  await page.getByLabel("Playback speed").selectOption("1.5");
  await expect.poll(async () => (await videoState(page)).rate).toBe(1.5);
  await blur(page);
  await page.keyboard.press(">");
  await expect.poll(async () => (await videoState(page)).rate).toBe(1.75);

  await page.keyboard.press("Space");
  await expect.poll(async () => (await videoState(page)).paused).toBe(true);

  await page.getByRole("button", { name: "Full screen" }).click();
  await expect(page.getByRole("button", { name: "Exit full screen" })).toBeVisible();
  // The player (canvas + controls) is what goes fullscreen; the canvas grows with it.
  const canvasHeight = await page.getByTestId("video-canvas").evaluate((c) => c.getBoundingClientRect().height);
  expect(canvasHeight).toBeGreaterThan(600);
  await page.getByRole("button", { name: "Exit full screen" }).click();
  await expect(page.getByRole("button", { name: "Full screen" })).toBeVisible();
});

test("queue: next/previous change the source and the canvas follows the new aspect ratio", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("region", { name: "Demo & test media" }).getByRole("button", { name: "Play all" }).click();
  await expect(page).toHaveURL(/demo=bars/);
  await startPlayback(page);
  const bars = await sampleCanvas(page, await demoLayout(page, "bars"));
  expect(bars.width / bars.height).toBeCloseTo(16 / 9, 1);

  const queue = page.getByRole("complementary", { name: "Up next" });
  await expect(queue.getByRole("listitem")).toHaveCount(3);

  const barsSrc = await currentSrc(page);
  await page.getByRole("button", { name: "Next video" }).click();
  await expect(page).toHaveURL(/demo=vertical/);
  await startPlayback(page, barsSrc);
  const verticalLayout = await demoLayout(page, "vertical");
  const vertical = await sampleCanvas(page, verticalLayout);
  expect(vertical.width / vertical.height).toBeCloseTo(9 / 16, 1);
  expect(vertical.red[0]).toBeGreaterThan(190);
  // The frame counter restarted with the new source.
  expect(vertical.frames).toBeLessThan(bars.frames + 200);

  const verticalSrc = await currentSrc(page);
  await blur(page);
  await page.keyboard.press("Shift+P");
  await expect(page).toHaveURL(/demo=bars/);
  await startPlayback(page, verticalSrc);
  const back = await sampleCanvas(page, await demoLayout(page, "bars"));
  expect(back.width / back.height).toBeCloseTo(16 / 9, 1);
});

test("favorites and continue watching persist in localStorage", async ({ page }) => {
  await openDemo(page, "bars");
  await page.getByRole("button", { name: "Favorite" }).click();
  await page.getByRole("button", { name: "Pause" }).click();
  await page.getByRole("slider", { name: "Seek" }).fill("7");
  await expect.poll(async () => Math.abs((await videoState(page)).time - 7)).toBeLessThan(0.3);

  await page.getByRole("link", { name: "yt-canvas home" }).click();
  const continueShelf = page.getByRole("region", { name: "Continue watching" });
  await expect(continueShelf.getByText("DEMO · Test pattern (16:9, 20 s)")).toBeVisible();
  await expect(page.getByRole("region", { name: "Favorites" }).getByText("DEMO · Test pattern (16:9, 20 s)")).toBeVisible();

  await page.reload();
  await expect(page.getByRole("region", { name: "Continue watching" })).toBeVisible();

  // Resuming starts near the saved position.
  await continueShelf.getByRole("link", { name: /Test pattern/ }).first().click();
  await startPlayback(page);
  expect((await videoState(page)).time).toBeGreaterThan(6);
  await expect(page.getByText(/Resumed at 0:0[67]/)).toBeVisible();
});

test("clear errors for invalid and unknown media", async ({ page }) => {
  await page.goto("/watch?v=not-valid");
  await expect(page.getByTestId("preparation-error")).toHaveAttribute("data-code", "invalid_input");
  await page.goto("/watch?demo=nope");
  await expect(page.getByTestId("preparation-error")).toHaveAttribute("data-code", "not_found");
  await page.goto("/nowhere");
  await expect(page.getByRole("heading", { name: "Page not found" })).toBeVisible();
});

test("decoder visibility strategies (diagnostic, Chromium)", async ({ page }, testInfo) => {
  const results: Record<string, { framesPerSecond: number; changed: boolean; mode: string }> = {};
  const layout = await demoLayout(page, "bars");
  for (const strategy of ["layered", "covered", "offscreen", "hidden"]) {
    await page.goto(`/watch?demo=bars&decoder=${strategy}`);
    let ok = true;
    try {
      await startPlayback(page);
    } catch {
      ok = false;
    }
    const a = await sampleCanvas(page, layout);
    await page.waitForTimeout(1000);
    const b = await sampleCanvas(page, layout);
    results[strategy] = { framesPerSecond: ok ? b.frames - a.frames : 0, changed: b.hash !== a.hash, mode: b.mode };
  }
  await testInfo.attach("decoder-strategies.json", { body: JSON.stringify(results, null, 2), contentType: "application/json" });
  console.log(`decoder strategies (${testInfo.project.name}): ${JSON.stringify(results)}`);
  // The default must work; the others are recorded for the README.
  expect(results.layered?.changed).toBe(true);
  expect(results.layered?.framesPerSecond).toBeGreaterThan(10);
});
